{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Terameprocol absolute oral bioavailability was approximately 2% in patients with recurrent high-grade gliomas, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Terbutaline tablet absolute oral bioavailability was 15.7% ± 4.8% versus IV in human subjects, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Prochlorperazine absolute oral bioavailability was 12.5% ± 4.3% in healthy male volunteers, below the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transferability absolute oral bioavailability measurements in humans are consistently below 20%, including approximately 2%, 8.6%, 10%, 12.5%, 14-15%, and 5.4%. The only numeric value above 20% is a conflicting retrospective halofantrine estimate and does not outweigh the consistent sub-threshold absolute data.",
  "evidence_gaps": [
    "One halofantrine absolute estimate (~30%) conflicts with multiple qualitative low-bioavailability reports; its retrospective separate-study design reduces its weight.",
    "Some evidence is qualitative or simulation-based rather than direct absolute measurements, but the direct absolute human data consistently support low bioavailability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

